import { registerWebComponents } from '@domg-wc/common';
import { VlUploadComponent } from '@domg-wc/components/form';

registerWebComponents([VlUploadComponent]);

const upload = document.querySelector('vl-upload');

// Bij vl-addedfile en vl-removedfile is event.detail.file het bestand, en event.detail.value de nieuwe waarde: een
// FormData met de geaccepteerde bestanden onder de name van het veld (of het id), of null zonder bestanden.
upload.addEventListener('vl-addedfile', (event) => {
    console.log(event.detail.file.name, upload.getFiles());
});

// vl-error volgt op een bestand dat niet voldoet, bv. te groot of één te veel; event.detail.errorMessage is de
// melding die ook bij het bestand verschijnt.
upload.addEventListener('vl-error', (event) => {
    console.log(event.detail.file.name, event.detail.errorMessage);
});

// Zonder auto-process laadt vl-upload niets op: upload.upload() stuurt de bestanden in de wachtrij naar url.
// vl-success volgt per bestand, met in event.detail.response het antwoord van de server.
upload.addEventListener('vl-success', (event) => {
    console.log(event.detail.file.name, event.detail.response);
});
